function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 values.';
  const n = nums.length;
  const seen = new Array(n).fill(false);
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 0 || v >= n) return 'Each value is an integer from 0 to n - 1.';
    if (seen[v]) return 'Each value from 0 to n - 1 appears exactly once.';
    seen[v] = true;
  }
  return null;
}

