function sortArray(nums) {
  const n = nums.length;
  const movesToIdentity = (perm, empty) => {
    const visited = new Array(n).fill(false);
    let moves = 0;
    for (let i = 0; i < n; i++) {
      if (perm[i] === i || visited[i]) {
        continue;
      }
      let length = 0;
      let hasEmpty = false;
      for (let j = i; !visited[j]; j = perm[j]) {
        visited[j] = true;
        length++;
        if (perm[j] === empty) {
          hasEmpty = true;
        }
      }
      moves += hasEmpty ? length - 1 : length + 1;
    }
    return moves;
  };
  const emptyFirst = movesToIdentity(nums, 0);
  const shifted = nums.map(value => (value + n - 1) % n);
  const emptyLast = movesToIdentity(shifted, n - 1);
  return Math.min(emptyFirst, emptyLast);
}

