function sortArray(nums) {
  const n = nums.length;
  const first = Array.from({ length: n }, (_, i) => i).join(',');
  const last = Array.from({ length: n }, (_, i) => (i + 1) % n).join(',');
  const start = nums.join(',');
  const dist = new Map([[start, 0]]);
  const queue = [nums.slice()];
  for (let head = 0; head < queue.length; head++) {
    const state = queue[head];
    const key = state.join(',');
    if (key === first || key === last) return dist.get(key);
    const hole = state.indexOf(0);
    for (let i = 0; i < n; i++) {
      if (i === hole) continue;
      const next = state.slice();
      next[hole] = next[i];
      next[i] = 0;
      const nextKey = next.join(',');
      if (!dist.has(nextKey)) {
        dist.set(nextKey, dist.get(key) + 1);
        queue.push(next);
      }
    }
  }
  return -1;
}

