function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : pick(2, 7);
  const shuffle = (arr) => {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  };
  const style = rand();
  if (style < 0.5) return [shuffle(Array.from({ length: n }, (_, i) => i))];
  // Nearly sorted: start from one of the sorted forms and swap a few pairs.
  const nums = style < 0.75 ? Array.from({ length: n }, (_, i) => i) : Array.from({ length: n }, (_, i) => (i + 1) % n);
  const swaps = size === 'large' ? pick(1, 200) : pick(0, 2);
  for (let s = 0; s < swaps; s++) {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    [nums[a], nums[b]] = [nums[b], nums[a]];
  }
  return [nums];
}
